19	// Pre-compiled regexes for read-only query detection
20	var (
21		readOnlyPrefixPatterns = []*regexp.Regexp{
22			regexp.MustCompile(`^\s*select\b`),
23			regexp.MustCompile(`^\s*show\b`),
24			regexp.MustCompile(`^\s*describe\b`),
25			regexp.MustCompile(`^\s*explain\b`),
26			regexp.MustCompile(`^\s*with\b`),
27		}
28	
29		showCreatePatterns = []*regexp.Regexp{
30			regexp.MustCompile(`^\s*show\s+create\s+table\b`),
31			regexp.MustCompile(`^\s*show\s+create\s+view\b`),
32			regexp.MustCompile(`^\s*show\s+create\s+schema\b`),
33			regexp.MustCompile(`^\s*show\s+create\s+materialized\s+view\b`),
34		}
35	
36		showPrefixPattern = regexp.MustCompile(`^\s*show\b`)
37	
38		safeStartPatterns = []*regexp.Regexp{
39			regexp.MustCompile(`^\s*select\b`),
40			regexp.MustCompile(`^\s*describe\b`),
41			regexp.MustCompile(`^\s*explain\b`),
42			regexp.MustCompile(`^\s*with\b`),
43		}
44	
45		// Pre-compiled write operation patterns
46		writeOpPatterns     []*regexp.Regexp
47		writeOpsExceptCreate []*regexp.Regexp
48	
49		// Pre-compiled sanitization patterns
50		singleQuoteLiteral = regexp.MustCompile(`'(?:[^']|'')*'`)
51		doubleQuoteIdent   = regexp.MustCompile(`"(?:[^"]|"")*"`)
52		backtickIdent      = regexp.MustCompile("`[^`]*`")
53		singleLineComment  = regexp.MustCompile(`--[^\r\n]*`)
54		multiLineComment   = regexp.MustCompile(`/\*[^*]*\*+(?:[^/*][^*]*\*+)*/`)
55	)
56	
57	func init() {
58		writeOps := []string{
59			"insert", "update", "delete", "drop", "create", "alter", "truncate",
60			"merge", "copy", "grant", "revoke", "commit", "rollback",
61			"call", "execute", "refresh", "set", "reset",
62		}
63		writeOpPatterns = make([]*regexp.Regexp, len(writeOps))
64		for i, op := range writeOps {
65			writeOpPatterns[i] = regexp.MustCompile(fmt.Sprintf(`\b%s\b`, regexp.QuoteMeta(op)))
66		}
67	
68		writeOpsNoCreate := []string{
69			"insert", "update", "delete", "drop", "alter", "truncate",
70			"merge", "copy", "grant", "revoke", "commit", "rollback",
71			"call", "execute", "refresh", "set", "reset",
72		}
73		writeOpsExceptCreate = make([]*regexp.Regexp, len(writeOpsNoCreate))
74		for i, op := range writeOpsNoCreate {
75			writeOpsExceptCreate[i] = regexp.MustCompile(fmt.Sprintf(`\b%s\b`, regexp.QuoteMeta(op)))
76		}
77	}
