86	// headerRoundTripper adds X-Trino-Source and X-Trino-User headers to requests
87	type headerRoundTripper struct {
88		base   http.RoundTripper
89		config *config.TrinoConfig
90	}
91	
92	func (t *headerRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
93		req = req.Clone(req.Context())
94	
95		// Set X-Trino-Source header for query attribution
96		if t.config.TrinoSource != "" {
97			req.Header.Set("X-Trino-Source", t.config.TrinoSource)
98		}
99	
100		// Set X-Trino-User header if impersonation is enabled
101		if t.config.EnableImpersonation {
102			if user, ok := req.Context().Value(impersonatedUserKey).(string); ok && user != "" {
103				req.Header.Set("X-Trino-User", user)
104			}
105		}
106	
107		return t.base.RoundTrip(req)
108	}
