117	// NewClient creates a new Trino client
118	func NewClient(cfg *config.TrinoConfig) (*Client, error) {
119		dsnURL := url.URL{
120			Scheme: cfg.Scheme,
121			User:   url.UserPassword(cfg.User, cfg.Password),
122			Host:   fmt.Sprintf("%s:%d", cfg.Host, cfg.Port),
123		}
124	
125		params := url.Values{}
126		params.Add("catalog", cfg.Catalog)
127		params.Add("schema", cfg.Schema)
128		params.Add("SSL", fmt.Sprintf("%t", cfg.SSL))
129		params.Add("SSLInsecure", fmt.Sprintf("%t", cfg.SSLInsecure))
130		params.Add("custom_client", "mcp-trino")
131	
132		dsnURL.RawQuery = params.Encode()
133		dsn := dsnURL.String()
134	
135		httpClient := &http.Client{
136			Transport: &headerRoundTripper{
137				base:   http.DefaultTransport,
138				config: cfg,
139			},
140		}
141		if err := trino.RegisterCustomClient("mcp-trino", httpClient); err != nil {
142			// Ignore "already registered" errors - this can happen in tests or when client is recreated
143			if !strings.Contains(err.Error(), "already registered") {
144				return nil, fmt.Errorf("failed to register custom HTTP client: %w", err)
145			}
146		}
147	
148		db, err := sql.Open("trino", dsn)
149		if err != nil {
150			// Sanitize error to prevent password exposure
151			sanitizedErr := sanitizeConnectionError(err, cfg.Password)
152			return nil, fmt.Errorf("failed to connect to Trino: %w", sanitizedErr)
153		}
154	
155		// Set connection pool parameters
156		db.SetMaxOpenConns(10)
157		db.SetMaxIdleConns(5)
158		db.SetConnMaxLifetime(5 * time.Minute)
159	
160		// Test the connection
161		if err := db.Ping(); err != nil {
162			closeErr := db.Close()
163			if closeErr != nil {
164				log.Printf("Error closing DB connection: %v", closeErr)
165			}
166			// Sanitize error to prevent password exposure
167			sanitizedErr := sanitizeConnectionError(err, cfg.Password)
168			return nil, fmt.Errorf("failed to ping Trino: %w", sanitizedErr)
169		}
170	
171		return &Client{
172			db:      db,
173			config:  cfg,
174			timeout: cfg.QueryTimeout,
175		}, nil
176	}
