194	// isReadOnlyQuery checks if the SQL query is read-only (SELECT, SHOW, DESCRIBE, EXPLAIN)
195	// This helps prevent SQL injection attacks by restricting the types of queries allowed
196	func isReadOnlyQuery(query string) bool {
197		// Convert to lowercase for case-insensitive comparison and normalize whitespace
198		queryLower := strings.ToLower(strings.TrimSpace(query))
199	
200		// Remove string literals and comments to avoid false positives
201		queryLower = sanitizeQueryForKeywordDetection(queryLower)
202	
203		// Replace any newline characters with spaces to normalize the query format
204		queryLower = strings.ReplaceAll(queryLower, "\n", " ")
205		queryLower = strings.ReplaceAll(queryLower, "\r", " ")
206	
207		// First check for SQL injection attempts with multiple statements
208		if strings.Contains(queryLower, ";") {
209			return false
210		}
211	
212		// Check if query starts with SELECT, SHOW, DESCRIBE, EXPLAIN or WITH (for CTEs)
213		// These are generally read-only operations. Use word boundaries for robustness.
214		// IMPORTANT: This check must come BEFORE write operation detection to avoid false positives
215		// (e.g., "SHOW CREATE TABLE" contains "create" but is read-only)
216		for _, re := range readOnlyPrefixPatterns {
217			if re.MatchString(queryLower) {
218				if isAllowedReadOnlyPattern(queryLower) {
219					return true
220				}
221			}
222		}
223	
224		// Check for write operations anywhere in the query using word boundaries
225		//  - https://trino.io/docs/current/sql.html - Main SQL reference
226		for _, re := range writeOpPatterns {
227			if re.MatchString(queryLower) {
228				return false
229			}
230		}
231	
232		return false
233	}
234	
235	// isAllowedReadOnlyPattern checks if a query matches known safe read-only patterns
236	// even if it contains keywords that might look like write operations
237	func isAllowedReadOnlyPattern(queryLower string) bool {
238		// SHOW CREATE statements are read-only (they just display DDL)
239		for _, re := range showCreatePatterns {
240			if re.MatchString(queryLower) {
241				return true
242			}
243		}
244	
245		// Other SHOW statements without CREATE are safe
246		if showPrefixPattern.MatchString(queryLower) {
247			for _, re := range writeOpsExceptCreate {
248				if re.MatchString(queryLower) {
249					return false
250				}
251			}
252			return true
253		}
254	
255		// SELECT, DESCRIBE, EXPLAIN, WITH without write operations are safe
256		for _, re := range safeStartPatterns {
257			if re.MatchString(queryLower) {
258				for _, wre := range writeOpPatterns {
259					if wre.MatchString(queryLower) {
260						return false
261					}
262				}
263				return true
264			}
265		}
266	
267		return false
268	}
269	
270	// sanitizeQueryForKeywordDetection removes string literals, quoted identifiers, and comments
271	// to prevent false positives when detecting write operations
272	func sanitizeQueryForKeywordDetection(query string) string {
273		query = singleQuoteLiteral.ReplaceAllString(query, "'LITERAL'")
274		query = doubleQuoteIdent.ReplaceAllString(query, "\"IDENTIFIER\"")
275		query = backtickIdent.ReplaceAllString(query, "`IDENTIFIER`")
276		query = singleLineComment.ReplaceAllString(query, "")
277		query = multiLineComment.ReplaceAllString(query, "")
278		return strings.TrimSpace(query)
279	}
