281	// getQueryUsername returns the username of the user executing the query if present in OAuth context
282	// This is used for query attribution (X-Trino-Client-Tags/Info) independent of impersonation
283	func getQueryUsername(ctx context.Context) string {
284		user, exists := oauth.GetUserFromContext(ctx)
285		if !exists || user == nil {
286			return ""
287		}
288		if user.Username != "" {
289			return user.Username
290		}
291		if user.Email != "" {
292			return user.Email
293		}
294		if user.Subject != "" {
295			return user.Subject
296		}
297		return ""
298	}
