307	// ExecuteQuery executes a SQL query and returns the results
308	func (c *Client) ExecuteQuery(query string) ([]map[string]interface{}, error) {
309		result, err := c.ExecuteQueryWithContext(context.Background(), query)
310		if err != nil {
311			return nil, err
312		}
313		return result.Rows, nil
