316	// ExecuteQueryWithContext executes a SQL query and returns the results
317	// It supports both:
318	// - User impersonation via X-Trino-User header (when EnableImpersonation is true)
319	// - Query attribution via X-Trino-Client-Tags/Info/Source (from OAuth user context)
320	func (c *Client) ExecuteQueryWithContext(ctx context.Context, query string) (*QueryResult, error) {
321		// Strip trailing semicolon that Trino doesn't allow
322		query = strings.TrimSuffix(strings.TrimSpace(query), ";")
323	
324		// SQL injection protection: only allow read-only queries unless explicitly allowed in config
325		if !c.config.AllowWriteQueries && !isReadOnlyQuery(query) {
326			return nil, fmt.Errorf("security restriction: only SELECT, SHOW, DESCRIBE, and EXPLAIN queries are allowed. " +
327				"Set TRINO_ALLOW_WRITE_QUERIES=true to enable write operations (at your own risk)")
328		}
329	
330		// Create context with timeout, preserving any impersonation data
331		queryCtx, cancel := context.WithTimeout(ctx, c.timeout)
332		defer cancel()
333	
334		// Build query arguments for attribution headers
335		// These are complementary to the X-Trino-User header set by RoundTripper
336		var queryArgs []interface{}
337		if userName := getQueryUsername(ctx); userName != "" {
338			queryArgs = append(queryArgs,
339				sql.Named("X-Trino-Client-Tags", userName),
340				sql.Named("X-Trino-Client-Info", userName),
341			)
342			// Only set X-Trino-Source if not already configured globally
343			if c.config.TrinoSource == "" {
344				queryArgs = append(queryArgs, sql.Named("X-Trino-Source", userName))
345			}
346		}
347	
348		// Execute the query with optional attribution headers
349		rows, err := c.db.QueryContext(queryCtx, query, queryArgs...)
350		if err != nil {
351			return nil, fmt.Errorf("query execution failed: %w", err)
352		}
353		defer func() {
354			if err := rows.Close(); err != nil {
355				log.Printf("Error closing rows: %v", err)
356			}
357		}()
358	
359		// Get column names
360		columns, err := rows.Columns()
361		if err != nil {
362			return nil, fmt.Errorf("failed to get column names: %w", err)
363		}
364	
365		// Prepare result container
366		maxRows := c.config.MaxRows
367		initialCap := 64
368		if maxRows > 0 && maxRows < initialCap {
369			initialCap = maxRows
370		}
371		results := make([]map[string]interface{}, 0, initialCap)
372		truncated := false
373	
374		// Iterate through rows
375		for rows.Next() {
376			if maxRows > 0 && len(results) >= maxRows {
377				truncated = true
378				break
379			}
380	
381			// Create a slice of interface{} to hold the values
382			values := make([]interface{}, len(columns))
383			valuePtrs := make([]interface{}, len(columns))
384	
385			// Initialize the pointers
386			for i := range values {
387				valuePtrs[i] = &values[i]
388			}
389	
390			// Scan the row into values
391			if err := rows.Scan(valuePtrs...); err != nil {
392				log.Printf("Error scanning row: %v", err)
393				continue
394			}
395	
396			// Create a map for the current row
397			rowMap := make(map[string]interface{})
398			for i, col := range columns {
399				val := values[i]
400				rowMap[col] = val
401			}
402	
403			results = append(results, rowMap)
404		}
405	
406		// When truncated, close rows immediately to stop server-side streaming
407		// before checking rows.Err() which could surface spurious cancel errors
408		if truncated {
409			if err := rows.Close(); err != nil {
410				log.Printf("Error closing rows after truncation: %v", err)
411			}
412			log.Printf("WARNING: Result truncated to %d rows (TRINO_MAX_ROWS limit). Add LIMIT to your query or increase TRINO_MAX_ROWS.", maxRows)
413		} else {
414			// Only check rows.Err() when we consumed the full result set
415			if err := rows.Err(); err != nil {
416				return nil, fmt.Errorf("error iterating rows: %w", err)
417			}
418		}
419	
420		return &QueryResult{
421			Rows:      results,
422			Truncated: truncated,
423			MaxRows:   maxRows,
424		}, nil
425	}
