427	// ListCatalogs returns a list of available catalogs
428	func (c *Client) ListCatalogs() ([]string, error) {
429		return c.ListCatalogsWithContext(context.Background())
430	}
431	
432	// ListCatalogsWithContext returns a list of available catalogs with context
433	func (c *Client) ListCatalogsWithContext(ctx context.Context) ([]string, error) {
434		result, err := c.ExecuteQueryWithContext(ctx, "SHOW CATALOGS")
435		if err != nil {
436			return nil, err
437		}
438	
439		catalogs := make([]string, 0, len(result.Rows))
440		for _, row := range result.Rows {
441			if catalog, ok := row["Catalog"].(string); ok {
442				catalogs = append(catalogs, catalog)
443			}
444		}
445	
446		// Apply catalog filtering if allowlist is configured
447		if len(c.config.AllowedCatalogs) > 0 {
448			catalogs = c.filterCatalogs(catalogs)
449		}
450	
451		return catalogs, nil
452	}
453	
454	// ListSchemas returns a list of schemas in the specified catalog
455	func (c *Client) ListSchemas(catalog string) ([]string, error) {
456		return c.ListSchemasWithContext(context.Background(), catalog)
457	}
458	
459	// ListSchemasWithContext returns a list of schemas in the specified catalog with context
460	func (c *Client) ListSchemasWithContext(ctx context.Context, catalog string) ([]string, error) {
461		if catalog == "" {
462			catalog = c.config.Catalog
463		}
464	
465		query := fmt.Sprintf("SHOW SCHEMAS FROM %s", catalog)
466		result, err := c.ExecuteQueryWithContext(ctx, query)
467		if err != nil {
468			return nil, err
469		}
470	
471		schemas := make([]string, 0, len(result.Rows))
472		for _, row := range result.Rows {
473			if schema, ok := row["Schema"].(string); ok {
474				schemas = append(schemas, schema)
475			}
476		}
477	
478		// Apply schema filtering if allowlist is configured
479		if len(c.config.AllowedSchemas) > 0 {
480			schemas = c.filterSchemas(schemas, catalog)
481		}
482	
483		return schemas, nil
484	}
485	
486	// ListTables returns a list of tables in the specified catalog and schema
487	func (c *Client) ListTables(catalog, schema string) ([]string, error) {
488		return c.ListTablesWithContext(context.Background(), catalog, schema)
489	}
490	
491	// ListTablesWithContext returns a list of tables in the specified catalog and schema with context
492	func (c *Client) ListTablesWithContext(ctx context.Context, catalog, schema string) ([]string, error) {
493		if catalog == "" {
494			catalog = c.config.Catalog
495		}
496		if schema == "" {
497			schema = c.config.Schema
498		}
499	
500		query := fmt.Sprintf("SHOW TABLES FROM %s.%s", catalog, schema)
501		result, err := c.ExecuteQueryWithContext(ctx, query)
502		if err != nil {
503			return nil, err
504		}
505	
506		tables := make([]string, 0, len(result.Rows))
507		for _, row := range result.Rows {
508			if table, ok := row["Table"].(string); ok {
509				tables = append(tables, table)
510			}
511		}
512	
513		// Apply table filtering if allowlist is configured
514		if len(c.config.AllowedTables) > 0 {
515			tables = c.filterTables(tables, catalog, schema)
516		}
517	
518		return tables, nil
519	}
520	
521	// GetTableSchema returns the schema of a table
522	func (c *Client) GetTableSchema(catalog, schema, table string) (*QueryResult, error) {
523		return c.GetTableSchemaWithContext(context.Background(), catalog, schema, table)
524	}
525	
526	// GetTableSchemaWithContext returns the schema of a table with context
527	func (c *Client) GetTableSchemaWithContext(ctx context.Context, catalog, schema, table string) (*QueryResult, error) {
528		// Resolve catalog/schema/table parameters first
529		parts := strings.Split(table, ".")
530		if len(parts) == 3 {
531			// If table is already fully qualified, extract components
532			catalog = parts[0]
533			schema = parts[1]
534			table = parts[2]
535		} else if len(parts) == 2 {
536			// If table has schema.table format
537			schema = parts[0]
538			table = parts[1]
539			if catalog == "" {
540				catalog = c.config.Catalog
541			}
542		} else {
543			// Use provided or default catalog and schema
544			if catalog == "" {
545				catalog = c.config.Catalog
546			}
547			if schema == "" {
548				schema = c.config.Schema
549			}
550		}
551	
552		// Check if table access is allowed when table allowlist is configured (after resolution)
553		if len(c.config.AllowedTables) > 0 {
554			if !c.isTableAllowed(catalog, schema, table) {
555				return nil, fmt.Errorf("table access denied: %s.%s.%s not in allowlist", catalog, schema, table)
556			}
557		}
558	
559		// Build and execute query with resolved parameters
560		query := fmt.Sprintf("DESCRIBE %s.%s.%s", catalog, schema, table)
561		return c.ExecuteQueryWithContext(ctx, query)
562	}
563	
564	// ExplainQuery returns the query execution plan for a given SQL query
565	func (c *Client) ExplainQuery(query string, format string) (*QueryResult, error) {
566		return c.ExplainQueryWithContext(context.Background(), query, format)
567	}
568	
569	// ExplainQueryWithContext returns the query execution plan for a given SQL query with context
570	func (c *Client) ExplainQueryWithContext(ctx context.Context, query string, format string) (*QueryResult, error) {
571		// Build EXPLAIN query with optional TYPE format (LOGICAL|DISTRIBUTED|VALIDATE|IO)
572		explainQuery := "EXPLAIN"
573		if f := strings.ToUpper(strings.TrimSpace(format)); f != "" {
574			switch f {
575			case "LOGICAL", "DISTRIBUTED", "VALIDATE", "IO":
576				explainQuery = fmt.Sprintf("EXPLAIN (TYPE %s)", f)
577			default:
578				return nil, fmt.Errorf("invalid EXPLAIN format: %q (allowed: LOGICAL, DISTRIBUTED, VALIDATE, IO)", format)
579			}
580		}
581		explainQuery = fmt.Sprintf("%s %s", explainQuery, query)
582	
583		return c.ExecuteQueryWithContext(ctx, explainQuery)
584	}
585	
586	// sanitizeConnectionError removes sensitive information from connection errors
587	func sanitizeConnectionError(err error, password string) error {
588		if err == nil {
589			return err
590		}
591	
592		errStr := err.Error()
593	
594		// Replace password in error message if it exists
595		if password != "" {
596			// Replace URL-encoded password
597			encodedPassword := url.QueryEscape(password)
598			errStr = strings.ReplaceAll(errStr, encodedPassword, "[PASSWORD_REDACTED]")
599	
600			// Replace plain password
601			errStr = strings.ReplaceAll(errStr, password, "[PASSWORD_REDACTED]")
602		}
603	
604		return fmt.Errorf("%s", errStr)
605	}
606	
607	// filterCatalogs filters a list of catalogs based on the allowlist configuration
608	func (c *Client) filterCatalogs(catalogs []string) []string {
609		if len(c.config.AllowedCatalogs) == 0 {
610			return catalogs
611		}
612	
613		filtered := make([]string, 0, len(catalogs))
614		for _, catalog := range catalogs {
615			if c.isCatalogAllowed(catalog) {
616				filtered = append(filtered, catalog)
617			}
618		}
619	
620		log.Printf("DEBUG: Catalog filtering: %d catalogs -> %d catalogs", len(catalogs), len(filtered))
621		return filtered
622	}
623	
624	// filterSchemas filters a list of schemas based on the allowlist configuration
625	func (c *Client) filterSchemas(schemas []string, catalog string) []string {
626		if len(c.config.AllowedSchemas) == 0 {
627			return schemas
628		}
629	
630		filtered := make([]string, 0, len(schemas))
631		for _, schema := range schemas {
632			if c.isSchemaAllowed(catalog, schema) {
633				filtered = append(filtered, schema)
634			}
635		}
636	
637		log.Printf("DEBUG: Schema filtering: %d schemas -> %d schemas", len(schemas), len(filtered))
638		return filtered
639	}
640	
641	// filterTables filters a list of tables based on the allowlist configuration
642	func (c *Client) filterTables(tables []string, catalog, schema string) []string {
643		if len(c.config.AllowedTables) == 0 {
644			return tables
645		}
646	
647		filtered := make([]string, 0, len(tables))
648		for _, table := range tables {
649			if c.isTableAllowed(catalog, schema, table) {
650				filtered = append(filtered, table)
651			}
652		}
653	
654		log.Printf("DEBUG: Table filtering: %d tables -> %d tables", len(tables), len(filtered))
655		return filtered
656	}
657	
658	// isCatalogAllowed checks if a catalog is in the allowed catalogs list
659	func (c *Client) isCatalogAllowed(catalog string) bool {
660		for _, allowed := range c.config.AllowedCatalogs {
661			if strings.EqualFold(catalog, allowed) {
662				return true
663			}
664		}
665		return false
666	}
667	
668	// isSchemaAllowed checks if a schema is in the allowed schemas list
669	func (c *Client) isSchemaAllowed(catalog, schema string) bool {
670		fullSchemaName := catalog + "." + schema
671		for _, allowed := range c.config.AllowedSchemas {
672			if strings.EqualFold(fullSchemaName, allowed) {
673				return true
674			}
675		}
676		return false
677	}
