680	func (c *Client) isTableAllowed(catalog, schema, table string) bool {
681		fullTableName := catalog + "." + schema + "." + table
682		for _, allowed := range c.config.AllowedTables {
683			if strings.EqualFold(fullTableName, allowed) {
684				return true
685			}
686		}
