// getQueryUsername returns the username of the user executing the query if present in context
// Falls back to "mcp-trino-user" when no OAuth user is present, ensuring Trino always
// receives identity information for query attribution.
func getQueryUsername(ctx context.Context) string {
	user, exists := oauth.GetUserFromContext(ctx)
	if !exists || user == nil {
		return "mcp-trino-user"
	}
	if user.Username != "" {
		return user.Username
	}
	if user.Email != "" {
		return user.Email
	}
	if user.Subject != "" {
		return user.Subject
	}
	return "mcp-trino-user"
}

