// hasRealOAuthUser returns true if a real OAuth user identity exists
// (not just the default fallback). Used to decide whether to send X-Trino-User
// as a per-query argument to Trino.
func hasRealOAuthUser(user *oauth.User) bool {
	return user != nil && (user.Username != "" || user.Email != "" || user.Subject != "")
}

// getOAuthUserAndUsername returns the OAuth user (if any) and the display username
// from context. This avoids redundant context lookups when both hasRealOAuthUser
// and getQueryUsername are needed.

